import CryptoKit
import Foundation

/// Every sha256 a bundled resource has ever had in git history.
///
/// Generated by `scripts/gen-seed-manifest.sh` into
/// `Resources/SeedManifest.json`. A copy in the user's Application Support
/// directory that still matches one of these hashes was never edited by the
/// user, even when it predates the `.seed-sha256` sidecar.
public struct SeedManifest {
    public static let empty = SeedManifest(entries: [:])

    /// The manifest shipped inside the runtime resource bundle.
    public static let shared: SeedManifest = loadBundled()

    public let entries: [String: Set<String>]

    public init(entries: [String: Set<String>]) {
        self.entries = entries
    }

    public func contains(relativePath: String, hash: String) -> Bool {
        entries[Self.normalize(relativePath)]?.contains(hash.lowercased()) ?? false
    }

    public func hashes(for relativePath: String) -> Set<String> {
        entries[Self.normalize(relativePath)] ?? []
    }

    /// Accepts both the resource-relative key (`Prompts/core/identity.md`) and
    /// the repository path it is generated from.
    static func normalize(_ path: String) -> String {
        var value = path
        let prefix = "Sources/JaplosRuntime/Resources/"
        if value.hasPrefix(prefix) { value.removeFirst(prefix.count) }
        while value.hasPrefix("./") { value.removeFirst(2) }
        while value.hasPrefix("/") { value.removeFirst() }
        return value
    }

    static func loadBundled() -> SeedManifest {
        var candidates: [URL] = []
        if let url = Bundle.module.url(forResource: "SeedManifest", withExtension: "json") {
            candidates.append(url)
        }
        if let url = Bundle.main.url(forResource: "SeedManifest", withExtension: "json") {
            candidates.append(url)
        }
        for url in candidates {
            guard let data = try? Data(contentsOf: url),
                  let raw = try? JSONDecoder().decode([String: [String]].self, from: data)
            else { continue }
            var entries: [String: Set<String>] = [:]
            for (key, values) in raw {
                entries[normalize(key)] = Set(values.map { $0.lowercased() })
            }
            return SeedManifest(entries: entries)
        }
        return .empty
    }
}

/// Tracks the hash of a file copied out of the bundle. An unchanged copy is
/// refreshed when the bundle changes. A file whose bytes differ from that hash
/// is treated as a user edit and left alone.
public enum SeededOverride {
    public static func sha256Hex(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    public static func sidecar(for file: URL) -> URL {
        URL(fileURLWithPath: file.path + ".seed-sha256")
    }

    public static func text(
        override: URL,
        bundled: URL?,
        relativePath: String? = nil,
        createIfMissing: Bool = false,
        manifest: SeedManifest = .shared
    ) -> String? {
        let fm = FileManager.default
        let bundledData = bundled.flatMap { try? Data(contentsOf: $0) }
        if !fm.fileExists(atPath: override.path) {
            guard let bundledData else { return nil }
            guard createIfMissing else { return String(data: bundledData, encoding: .utf8) }
            try? fm.createDirectory(at: override.deletingLastPathComponent(), withIntermediateDirectories: true)
            try? bundledData.write(to: override, options: .atomic)
            writeHash(sha256Hex(bundledData), for: override)
            return String(data: bundledData, encoding: .utf8)
        }
        guard let overrideData = try? Data(contentsOf: override) else { return nil }
        let overrideHash = sha256Hex(overrideData)
        let recorded = (try? String(contentsOf: sidecar(for: override), encoding: .utf8))?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let recordedHash = (recorded?.isEmpty == false) ? recorded : nil
        let bundledHash = bundledData.map { sha256Hex($0) }
        if let bundledData, let recordedHash, overrideHash == recordedHash, bundledHash != recordedHash {
            try? bundledData.write(to: override, options: .atomic)
            writeHash(sha256Hex(bundledData), for: override)
            return String(data: bundledData, encoding: .utf8)
        }
        if recordedHash == nil, let bundledData, overrideHash == sha256Hex(bundledData) {
            writeHash(overrideHash, for: override)
            return String(data: bundledData, encoding: .utf8)
        }
        // A1: a copy that predates the sidecar. If its bytes match a version
        // that shipped in some release, the user never edited it, so refresh
        // from the bundle and start tracking it. Anything else is a real edit.
        if recordedHash == nil, let bundledData, bundledHash != overrideHash,
           let relativePath, manifest.contains(relativePath: relativePath, hash: overrideHash) {
            try? bundledData.write(to: override, options: .atomic)
            writeHash(sha256Hex(bundledData), for: override)
            return String(data: bundledData, encoding: .utf8)
        }
        return String(data: overrideData, encoding: .utf8)
    }

    private static func writeHash(_ hash: String, for file: URL) {
        try? Data(hash.utf8).write(to: sidecar(for: file), options: .atomic)
    }
}
